import type { CapacitorConfig } from "@capacitor/cli";

/*
 * The app is a native shell around the hosted website (apps/frontend): pages are server-rendered and the
 * session lives in httpOnly cookies on that origin, so the WebView loads the site instead of a bundle.
 * www/ only holds the offline page shown when the site cannot be reached (generated by scripts/build-www.mjs).
 *
 * CAP_SERVER_URL is read when running `pnpm sync` and baked into the native projects:
 *   production   CAP_SERVER_URL=https://your-domain pnpm sync
 *   iOS sim      CAP_SERVER_URL=http://localhost:3000 pnpm sync
 *   Android emu  CAP_SERVER_URL=http://localhost:3000 pnpm sync  (+ adb reverse tcp:3000 tcp:3000)
 *
 * appId is permanent once the app is in a store; it is also the URL scheme (MOBILE_APP_SCHEME on the API).
 */
const serverUrl = (process.env.CAP_SERVER_URL ?? "http://localhost:3000").replace(/\/+$/, "");

const config: CapacitorConfig = {
  appId: "com.fahmialfareza.familytree",
  appName: "Sakdulur",
  webDir: "www",
  appendUserAgent: "FamilyTreeApp",
  server: {
    url: serverUrl,
    // Plain http is only for local development servers.
    cleartext: serverUrl.startsWith("http://"),
    errorPath: "offline.html",
  },
  ios: {
    contentInset: "never",
  },
  android: {
    allowMixedContent: false,
  },
  plugins: {
    SplashScreen: {
      // Hidden by the site as soon as it renders (components/providers/native-bridge.tsx); this is the cap.
      launchShowDuration: 3000,
      launchAutoHide: true,
      backgroundColor: "#f9f6ef",
      showSpinner: false,
    },
    SystemBars: {
      insetsHandling: "css",
      initialViewportFitValueHint: "cover",
    },
  },
};

export default config;
